// Package session opens a forge session and remembers its token.
//
// It is the one place that knows both backends exist, and the only reason it is
// a package of its own: internal/forge must not import a backend (a domain
// package cannot depend on its implementations), and a backend must not import
// its sibling. Something above both has to choose, and this is it.
//
// The credential store is **not** forge-shaped — Storage is keyed on a URL and
// knows nothing else — so the loading and forgetting of a token are the same
// code whichever platform the context targets. Only opening a session differs,
// and only in which constructor it calls.
package session

import (
	"context"
	"fmt"

	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/credentials"
	"github.com/anthnel/devdesk/internal/forge"
	githubforge "github.com/anthnel/devdesk/internal/forge/github"
	gitlabforge "github.com/anthnel/devdesk/internal/forge/gitlab"
)

// Auth opens sessions against a host and remembers their tokens.
type Auth struct {
	storage credentials.Storage
}

// NewAuth builds an Auth over a secret store. A nil store is legitimate: the
// session still opens, and nothing is remembered.
func NewAuth(storage credentials.Storage) *Auth {
	return &Auth{storage: storage}
}

// Result is a live session, plus whatever could not be saved about it.
type Result struct {
	Forge forge.Forge
	User  forge.User
	// SaveWarning is set when the session opened but the token could not be
	// stored. It is not an error: the session is valid, only its persistence
	// failed, and telling the user they are not logged in would be false.
	SaveWarning string
}

// Backend builds a client for a platform, without opening a session.
//
// The default is GitLab, matching config.applyDefaults: an unknown type has
// already been normalised by the time a context is loaded, and falling through
// to the one backend that has always existed is better than returning an error
// nothing can act on.
func Backend(forgeType, url, token string) (forge.Forge, error) {
	switch forgeType {
	case config.ForgeGitHub:
		return githubforge.New(url, token)
	default:
		return gitlabforge.New(url, token)
	}
}

// Authenticate opens a session and saves the token.
func (a *Auth) Authenticate(ctx context.Context, forgeType, url, token string) (*Result, error) {
	result, err := a.AuthenticateOnly(ctx, forgeType, url, token)
	if err != nil {
		return nil, err
	}

	if a.storage != nil {
		if err := a.storage.Save(url, token); err != nil {
			result.SaveWarning = fmt.Sprintf("The token was not saved: %v. You will have to enter it again next launch.", err)
		}
	}

	return result, nil
}

// AuthenticateOnly opens a session and writes nothing. It is the auto-login
// path, whose token already comes from the store.
func (a *Auth) AuthenticateOnly(ctx context.Context, forgeType, url, token string) (*Result, error) {
	backend, err := Backend(forgeType, url, token)
	if err != nil {
		return nil, fmt.Errorf("failed to create client: %w", err)
	}

	// CurrentUser is the connection test: authentication succeeded exactly when
	// the host answers with who the token belongs to.
	user, err := backend.CurrentUser(ctx)
	if err != nil {
		return nil, fmt.Errorf("authentication failed: %w", err)
	}

	return &Result{Forge: backend, User: user}, nil
}

// LoadCredentials reads a stored token.
//
// It takes no forge type, and that is not an oversight: the store is keyed on
// the URL, so a context that switched platform without changing host finds the
// token it already had — which is right, because it is the same host asking.
func (a *Auth) LoadCredentials(url string) (string, error) {

package main

import (
	"fmt"
	"log"
	"os"

	"github.com/anthnel/devdesk/internal/app"
	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/ui/theme"
	tea "github.com/charmbracelet/bubbletea"
)

func getCurrentContextName() string {
	ctx, err := config.GetCurrentContext()
	if err != nil || ctx == "" {
		return "default"
	}
	return ctx
}

// main runs the TUI. There is no subcommand any more.
//
// `dk mcp` served the MCP server on stdio (§3.38) and is gone with it (§3.61):
// the server now lives in this process, over HTTP, started by the router. What
// that deletes is the flag set, the argument dispatch, and the ordering
// constraint that used to sit here — everything below writes to stdout, and in
// stdio stdout *was* the protocol channel, so a single warning printed before
// the server started made the client report a JSON parse error naming nothing.
// Over HTTP the two do not share a channel, so the constraint is gone rather
// than relaxed.
func main() {
	runTUI()
}

func runTUI() {
	// Force TrueColor if Windows Terminal is detected (WSL does not propagate COLORTERM)
	if os.Getenv("WT_SESSION") != "" && os.Getenv("COLORTERM") == "" {
		_ = os.Setenv("COLORTERM", "truecolor")
	}

	// Load the configuration
	cfg, err := config.Load()
	if err != nil {
		fmt.Printf("Error loading config: %v\n", err)
		fmt.Println("Using default configuration.")
		cfg = config.Default()
	}

	// Create the config directory if it does not exist
	if err := config.EnsureConfigDir(); err != nil {
		fmt.Printf("Warning: Could not create config directory: %v\n", err)
	}

	// Always enable logging to a file to avoid polluting the TUI interface
	logFile, err := tea.LogToFile(cfg.App.LogFile, "debug")
	if err != nil {
		fmt.Printf("Warning: Could not create log file: %v\n", err)
	} else {
		defer func() { _ = logFile.Close() }()
		log.Printf("=== DevDesk Started ===")
		log.Printf("Config loaded from context: %s", getCurrentContextName())
		log.Printf("Log file: %s", cfg.App.LogFile)
		log.Printf("DEBUG mode: %v", len(os.Getenv("DEBUG")) > 0)
	}

	// Load and apply the saved theme
	if cfg.App.Theme != "" && cfg.App.Theme != "dark" {
		t, err := theme.LoadTheme(cfg.App.Theme)
		if err != nil {
			log.Printf("Warning: Could not load theme '%s': %v, using default", cfg.App.Theme, err)
		} else {
			theme.ApplyTheme(t)
			theme.CurrentThemeName = cfg.App.Theme
			log.Printf("Theme loaded: %s", cfg.App.Theme)
		}
	}

	// Create the application with the router
	m := app.New(cfg)

	// Bubble Tea program options
	opts := []tea.ProgramOption{
		tea.WithAltScreen(), // Full-screen mode
	}

	// Start the Bubble Tea program
	p := tea.NewProgram(m, opts...)

	// The router needs the handle before the loop starts: an MCP request
	// reaches Update() through p.Send, and there is no other legal door
	// (Rule 110). Written here, once, while nothing else is running.
	m.AttachProgram(p)

	if _, err := p.Run(); err != nil {
		fmt.Printf("Error running application: %v\n", err)
		os.Exit(1)
	}
}

package config

import (
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strings"

	"gopkg.in/yaml.v3"
)

// Config represents the application's complete configuration
type Config struct {
	App      AppConfig      `yaml:"app"`
	Status   StatusConfig   `yaml:"status"`
	Forge    ForgeConfig    `yaml:"forge"`
	Registry RegistryConfig `yaml:"registry"`
	Scan     ScanConfig     `yaml:"scan"`
	Network  NetworkConfig  `yaml:"network"`
	MCP      MCPConfig      `yaml:"mcp"`

	// GitLab is what `forge:` replaced. Same treatment as Docker above, and for
	// the same reason: a context targets one forge, so the section is named
	// after the role rather than after the one implementation there was.
	//
	// Deprecated: use Forge.
	GitLab GitLabConfig `yaml:"gitlab,omitempty"`
}

// MCPConfig governs the MCP server the TUI serves over HTTP (§3.61).
//
// It was a read-only stdio subcommand, `dk mcp` (§3.38). Three of that entry's
// decisions were reversed together: an agent running in a container cannot
// execute the host binary, which was §3.38's own open question 1 and became the
// only case anyone had.
//
// Enabled is false by default and that is the whole safety story: turning it on
// is the moment the user decides an agent may reach this context. Nothing
// migrates it, and nothing turns it on as a side effect.
//
// **What it means widened with §3.61, and nothing re-asks.** Under §3.38 it
// meant a read-only server on stdio, started by the client, with no listener at
// all; it now opens a loopback port and — `expose` being empty by default —
// serves the action tier as well. A context that said yes to the first is not
// asked again about the second, and a file written before §3.61 is recognisable
// (it carries no `listen`), so a narrower default was available and was
// deliberately not taken: the setting has always meant "an agent may reach this
// context", the widening is the entry's whole subject, and a migration would be
// ceremony around a decision its only user had just made. It is written here
// rather than left for someone to discover.
//
// There is no setting for the `Match` of a secret finding, and its absence is
// the guarantee. The entry proposed `redact_secret_matches: true` while also
// classing the string itself as never exposed — a setting whose other value is
// refused is a parameter that has to be ignored (§3.39). Worse, `false` is a
// bool's zero value, so every file written before the key existed would decode
// to "do not redact": the exact shape of D12. The tool schemas simply have
// nowhere to carry the string, which is the guarantee `context_get` already
// gets by construction (§3.9).
type MCPConfig struct {
	// Enabled decides whether the TUI serves at all. The refusal names this
	// setting and the context, because activating it in the wrong one is
	// otherwise an hour spent looking at a server that will not start.
	Enabled bool `yaml:"enabled"`

	// Expose is an **allow-list** of tool names; empty means every declared
	// tool. It is not a deny-list, for the reason §3.38 gives in the other
	// direction: a tool never registered cannot fail to be excluded, whereas a
	// deny-list is one forgotten line away from exposing what arrives next.
	Expose []string `yaml:"expose,omitempty"`

	// Listen is the address the server binds, and it is a loopback address
	// because that is both the most closed bind available and the one that
	// works: on Docker Desktop a container reaching `host.docker.internal`
	// arrives at the host's loopback, so a sandboxed agent is served without
	// the LAN ever being offered the port. The sandbox's own network policy is
	// a second lock — the port has to be allowed there by name.
	//
	// It is a setting rather than a literal for one reason, and it is not
	// configurability: on native Linux Docker `host.docker.internal` does not
	// reach the host's loopback, and the bridge gateway would have to be bound
	// instead. That case does not exist here and is not handled — but a literal
	// would have to be rewritten, where a setting has to be documented.
	//
	// An empty value means the default, never "listen nowhere": the zero value
	// of a string cannot be allowed to read as a choice, which is the shape of
	// D12. applyDefaults fills it.
	Listen string `yaml:"listen,omitempty"`
}

// DefaultMCPListen is where the server binds when the context does not say.
//
// Loopback, and a port high enough to be out of the way. It is named rather
// than inlined because applyDefaults and Default both need it, and a second
// literal is how the two drift.
const DefaultMCPListen = "127.0.0.1:7777"

// NetworkConfig holds what the netdiag view runs on.
type NetworkConfig struct {
	// CheckTimeout is how long one probe waits for an answer, in seconds.
	//
	// One setting rather than five: netcheck held 5 s for DNS and the dial, 8 s
	// for TLS and HTTP and 4 s for the ping, and nothing anywhere argued for the
	// split — it read as five separate guesses. The default is the old maximum,
	// so nothing that answers today starts failing; the cost is that an
	// unreachable host now spends 8 s on DNS instead of 5, which the staged
	// progress line makes legible rather than mysterious.
	CheckTimeout int `yaml:"check_timeout"`

	// PingCount is how many ICMP echo requests one reachability probe sends.
	PingCount int `yaml:"ping_count"`

	// CertExpiryWarnDays is how close a certificate may come to expiring before
	// the TLS check warns. Thirty days is a renewal cycle.
	CertExpiryWarnDays int `yaml:"cert_expiry_warn_days"`

	// PortsRefreshInterval is how often the Ports tab re-reads the socket
	// table, in seconds.
	PortsRefreshInterval int `yaml:"ports_refresh_interval"`
}

// Network defaults. They are the values internal/netcheck and the netdiag view
// held as constants before they became settings, so a config that predates them
// behaves exactly as it did — except CheckTimeout, which is the old maximum
// rather than any one of the five values it replaces.
const (
	DefaultCheckTimeout         = 8
	DefaultPingCount            = 3
	DefaultCertExpiryWarnDays   = 30
	DefaultPortsRefreshInterval = 2
)

// AppConfig holds the app's global settings
type AppConfig struct {
	Theme           string `yaml:"theme"`
	LogFile         string `yaml:"log_file"`
	DefaultView     string `yaml:"default_view"`
	WorkspacesDir   string `yaml:"workspaces_dir"`
	IDECommand      string `yaml:"ide_command"`
	TerminalCommand string `yaml:"terminal_command"` // e.g. "kitty --directory" — empty = auto-detect

	// TerminalNewWindow decides what T does: open a shell in place, suspending
	// the TUI (false, the default), or launch a separate terminal window (true).
	//
	// It is a setting rather than a second key because the capability depends on
	// the environment and not on the intent: no window can be opened under WSL,
	// and through SSH there is none to open. A key that is inert on two setups
	// out of three is worse than a setting that is simply off there (§3.26).
	TerminalNewWindow bool `yaml:"terminal_new_window"`

	// ShowHiddenFiles decides whether the workspaces view lists entries whose
	// name starts with a dot. False is the default because that is what the
	// view has always done, so an existing config keeps its meaning and there
	// is nothing to migrate.
	//
	// It governs the listing *and* the nested-repo discovery behind S, F and A:
	// what the view shows is what those act on, and two rules for one question
	// would let a repository be a visible row and an invisible target at once.
	ShowHiddenFiles bool `yaml:"show_hidden_files"`

	// SecretBackend pins where secrets are stored: "auto" (default), "keyring"
	// for the host secret manager only, or "git-credential" for git's helper.
	// See credentials.Select for what each one resolves to.
	SecretBackend string `yaml:"secret_backend"`

	// ContainerEngine names the engine DevDesk drives: "auto" (default, docker
	// if it is on PATH and podman otherwise), "docker", "podman", or an
	// explicit path to a binary. See engine.Resolve.
	//
	// It sits in `app` beside ide_command and terminal_command — this section
	// already holds the external tools the application drives — and
	// deliberately not in `network`, which carries only netcheck's dials
	// despite once being called `docker` (§3.67).
	ContainerEngine string `yaml:"container_engine"`
}

// ForgeConfig is the code-hosting platform this context targets — exactly one,
// never two (§3.6).
//
// The token is not here: it lives in the host's secret manager
// (§3.9). A `token:` left by an earlier version is moved into the
// store and then removed from the file — see secrets.go.
type ForgeConfig struct {
	// Type names the backend: "gitlab" or "github". It is **declared, never
	// sniffed** — the registry `provider` field is the precedent (§3.8), and
	// `git.acme.com` is exactly the URL that cannot be told apart.
	//
	// Empty means "gitlab", which is what every file written before this key
	// existed meant.
	Type string `yaml:"type"`

	URL                string          `yaml:"url"`
	DefaultParentGroup string          `yaml:"default_parent_group"`
	DefaultVisibility  string          `yaml:"default_visibility"`
	CloneMethod        string          `yaml:"clone_method"`
	Pull               ForgePullConfig `yaml:"pull"`
}

// ForgePullConfig holds the configuration for synchronization
type ForgePullConfig struct {
	ParallelJobs    int  `yaml:"parallel_jobs"`
	IncludeArchived bool `yaml:"include_archived"`
}

// GitLabConfig is the shape `gitlab:` had. It is read at load and migrated into
// ForgeConfig; nothing else may use it.
//
// Deprecated: use ForgeConfig.
type GitLabConfig struct {
	URL                string           `yaml:"url,omitempty"`
	DefaultParentGroup string           `yaml:"default_parent_group,omitempty"`
	DefaultVisibility  string           `yaml:"default_visibility,omitempty"`
	CloneMethod        string           `yaml:"clone_method,omitempty"`
	Pull               GitLabPullConfig `yaml:"pull,omitempty"`
}

// GitLabPullConfig is `gitlab.pull:`.
//
// Deprecated: use ForgePullConfig.
type GitLabPullConfig struct {
	ParallelJobs    int  `yaml:"parallel_jobs,omitempty"`
	IncludeArchived bool `yaml:"include_archived,omitempty"`
}

// RegistryItem represents a single Docker/OCI registry with optional alias support.
// The password is NOT stored here; it is persisted via `docker login` / system credential helper.
type RegistryItem struct {
	// Slug identifies the entry inside DevDesk: it is what a member points at
	// and what the group cache is keyed on. Everything Docker-facing stays keyed
	// on the URL, because that is what Docker itself is keyed on — which is
	// exactly why the URL is the wrong thing to hang a parent link on, editing
	// one would silently orphan the group's members (§3.8, decision 1).
	// Filled in at load for a config that predates it; see registries.go.
	Slug string `yaml:"slug"`
	// Kind is "registry" or "group". A group fronts several registries and is
	// pullable itself, so both kinds share this one list (§3.8, decision A).
	Kind string `yaml:"kind,omitempty"`
	// Parent is the slug of the group this entry belongs to. Config entries are
	// what the user declares and normally carry none; it is discovered members,
	// which live in the group cache, that point back at their group.
	Parent string `yaml:"parent,omitempty"`
	// Provider is the repository manager serving a group — nexus, harbor,
	// artifactory, gitlab or generic. Declared rather than sniffed from the URL.
	Provider string `yaml:"provider,omitempty"`
	URL      string `yaml:"url"`
	Username string `yaml:"username"`
	Alias    string `yaml:"alias"`
	// RepoPrefix is what goes in front of the repository name to reach this
	// entry: `(url, repo_prefix)` is the whole address, and browse and pull both
	// derive from it, which is what stops them meaning two different repositories
	// (D39, §3.18).
	//
	// It is declared rather than sniffed, and for the same reason `provider` is:
	// whether a repository manager answers on a path prefix, a dedicated
	// connector port or a subdomain is a setting on that repository, and the one
	// endpoint that would say so is the one an ordinary pull account is refused.
	// Empty is the ordinary case — a registry reached at its own host.
	RepoPrefix string `yaml:"repo_prefix,omitempty"`
	// AuthMode says whether DevDesk may send stored credentials to this entry:
	// "credentials" or "anonymous", plus "inherit" for a member that takes its
	// group's. It is the only per-member override the credential store can
	// represent — see registries.go.
	AuthMode string `yaml:"auth_mode"`
	// AuthEnabled is what auth_mode replaced. It is read once at load, migrated
	// into AuthMode and cleared, so it disappears from the file on the next save.
	//
	// Deprecated: use AuthMode.
	AuthEnabled bool `yaml:"auth_enabled,omitempty"`
	// ManagementURL is optional. Set it when the Docker registry URL differs from the
	// URL used by the repository manager's API (e.g. Nexus connector subdomains,
	// Artifactory virtual repos). The group member discovery uses this URL instead of
	// the registry URL. Example: "https://nexus.example.com/repository/docker-group".
	ManagementURL string `yaml:"management_url,omitempty"`
}

// RegistryConfig holds the OCI registry configuration
//
// As with GitLabConfig, the password is not here (§3.9).
type RegistryConfig struct {
	URL                 string         `yaml:"url,omitempty"`
	Username            string         `yaml:"username,omitempty"`
	TemplatesRepository string         `yaml:"templates_repository"`
	CacheDir            string         `yaml:"cache_dir"`
	Registries          []RegistryItem `yaml:"registries,omitempty"`
}

// Tool source preferences. They say where a scanner is run from, which used to
// be decided for the user: detection resolved the binary first and only reached
// for Docker in the else, so a binary on PATH always won (D27).
const (
	// ToolSourceAuto keeps the historical resolution: the binary when there is
	// one, the Docker image otherwise. The default, so existing configs do not
	// change meaning.
	ToolSourceAuto = "auto"
	// ToolSourceBinary runs the configured path, else the name on PATH — and
	// fails when neither exists rather than falling back to Docker. The silent
	// fallback is what kept D27 invisible.
	ToolSourceBinary = "binary"
	// ToolSourceImage runs the Docker image even when a binary is installed.
	ToolSourceImage = "image"
)

// ScanConfig holds the configuration for security scans
type ScanConfig struct {
	TrivySource        string `yaml:"trivy_source"`         // auto | binary | image
	TrivyPath          string `yaml:"trivy_path"`           // Custom path to trivy (optional)
	TrivyImage         string `yaml:"trivy_image"`          // Docker image for trivy (default: aquasec/trivy)
	UseTrivyServer     bool   `yaml:"use_trivy_server"`     // Enables client-server mode; trivy_server is ignored if false
	TrivyServer        string `yaml:"trivy_server"`         // Trivy server URL (client-server mode)
	GitleaksSource     string `yaml:"gitleaks_source"`      // auto | binary | image
	GitleaksPath       string `yaml:"gitleaks_path"`        // Custom path to gitleaks (optional)
	GitleaksImage      string `yaml:"gitleaks_image"`       // Docker image for gitleaks (default: zricethezav/gitleaks)
	PlumberSource      string `yaml:"plumber_source"`       // auto | binary | image
	PlumberPath        string `yaml:"plumber_path"`         // Custom path to plumber (optional)
	PlumberImage       string `yaml:"plumber_image"`        // Docker image for plumber (default: getplumber/plumber)
	CacheDir           string `yaml:"cache_dir"`            // Report cache
	MaxCachedReports   int    `yaml:"max_cached_reports"`   // Max number of reports kept
	Timeout            int    `yaml:"timeout"`              // Timeout in seconds
	MaxConcurrentScans int    `yaml:"max_concurrent_scans"` // Max number of parallel scans

	// Scan options (persisted from the security view)
	EnableVuln      bool   `yaml:"enable_vuln"`
	EnableSecret    bool   `yaml:"enable_secret"`
	EnableMisconfig bool   `yaml:"enable_misconfig"`
	EnableLicense   bool   `yaml:"enable_license"`
	IgnoreUnfixed   bool   `yaml:"ignore_unfixed"`
	IgnoreEOL       bool   `yaml:"ignore_eol"`
	GitleaksHistory bool   `yaml:"gitleaks_history"`
	GitleaksConfig  string `yaml:"gitleaks_config"`

	// EnableCIScore runs plumber over the repository's CI configuration.
	//
	// The "all disabled means never configured" migration reads it and never
	// writes it. Reading it, because "the four off and CI on" is a deliberate
	// configuration that must not have vuln and secret forced back on; never
	// writing it, because this key is newer than the four and an absent
	// enable_ci_score means the user has not asked for it, not that the file
	// predates the question.
	EnableCIScore bool `yaml:"enable_ci_score"`
	// PlumberConfig is the rules file for every repository of the context, in
	// place of the .plumber.yaml plumber looks for in each one. Made absolute at
	// load for §3.50's reason: a relative path means DevDesk's working directory
	// in binary mode and the container's in Docker mode.
	PlumberConfig string `yaml:"plumber_config"`
}

// StatusConfig holds the configuration for monitoring
type StatusConfig struct {
	RefreshInterval int               `yaml:"refresh_interval"`
	Timeout         int               `yaml:"timeout"` // in seconds
	AutoRefresh     bool              `yaml:"auto_refresh"`
	Components      []ComponentConfig `yaml:"components"`
}

// ComponentConfig represents a component to monitor
type ComponentConfig struct {
	Name    string `yaml:"name"`
	Type    string `yaml:"type"`              // http, https, icmp, dns
	Target  string `yaml:"target"`            // URL, IP, or hostname
	Timeout int    `yaml:"timeout,omitempty"` // In seconds

	// Legacy support
	URL string `yaml:"url,omitempty"` // Deprecated, use Target

	// ICMP specific
	Count int `yaml:"count,omitempty"` // Number of pings

	// DNS specific
	Nameserver string `yaml:"nameserver,omitempty"` // Custom DNS server
}

// Load loads the configuration from the current context
func Load() (*Config, error) {
	ctx, err := GetCurrentContext()
	if err != nil {
		// Fallback to default on error
		ctx = "default"
	}

	cfg, err := LoadContext(ctx)
	if err != nil {
		// If the file does not exist, return the default config
		if os.IsNotExist(err) || strings.Contains(err.Error(), "does not exist") {
			return Default(), nil
		}
		// Otherwise (parsing error, permission error, etc.), propagate the error
		return nil, err
	}

	return cfg, nil
}

// applyDefaults applies the default values to a configuration.
// Returns an error when the file cannot be normalized — today
// only for registries (duplicate slug, missing parent group).
func applyDefaults(cfg *Config) error {
	homeDir, _ := os.UserHomeDir()

	// `gitlab:` → `forge:`, and it runs **first**. That is not tidiness: every
	// default below writes into cfg.Forge, so a migration placed after them
	// would find a block that is no longer empty and take the field-by-field
	// path — where every field is already filled with a default, and the user's
	// own `parallel_jobs: 7` is silently dropped. Measured, not theorised: it
	// is what the first draft did, and the retired-keys test caught it.
	//
	// The other half of the reason is `docker:` → `network:`'s: yaml.Unmarshal
	// is not strict here, so an un-migrated block is dropped in silence, and the
	// silence would point a context at no host at all.
	migrateGitLabSection(cfg)

	// "dark" was a third name for the built-in theme: LoadTheme accepts "",
	// "dark" and "default" alike, but ListThemes only ever offers "default", so
	// a config saying "dark" named a theme no picker could show. Normalised at
	// load; LoadTheme still accepts the old name for a file not yet rewritten.
	if cfg.App.Theme == "" || cfg.App.Theme == "dark" {
		cfg.App.Theme = "default"
	}
	if cfg.App.LogFile == "" {
		cfg.App.LogFile = filepath.Join(homeDir, ".devdesk", "devdesk.log")
	}
	if cfg.App.DefaultView == "" {
		cfg.App.DefaultView = "dashboard"
	}
	if cfg.App.WorkspacesDir == "" {
		cfg.App.WorkspacesDir = filepath.Join(homeDir, "workspaces")
	}
	if cfg.App.IDECommand == "" {
		cfg.App.IDECommand = "code"
	}
	// Left empty, credentials.Select already treats this as "auto"; naming it
	// keeps the setting inside the closed set the configuration view cycles
	// through, so the first arrow press does not jump somewhere arbitrary.
	if cfg.App.SecretBackend == "" {
		cfg.App.SecretBackend = "auto"
	}
	// Same reason: engine.Resolve reads "" as auto, but the configuration view
	// cycles a closed set and a value outside it has nowhere to start from.
	if cfg.App.ContainerEngine == "" {
		cfg.App.ContainerEngine = EngineAuto
	}
	if cfg.Status.RefreshInterval == 0 {
		cfg.Status.RefreshInterval = 10
	}
	if cfg.Status.Timeout == 0 {
		cfg.Status.Timeout = 5
	}
	if cfg.Forge.Type == "" {
		cfg.Forge.Type = ForgeGitLab
	}
	if cfg.Forge.DefaultVisibility == "" {
		cfg.Forge.DefaultVisibility = "private"
	}
	if cfg.Forge.CloneMethod == "" {
		cfg.Forge.CloneMethod = "https"
	}
	if cfg.Forge.Pull.ParallelJobs == 0 {
		cfg.Forge.Pull.ParallelJobs = 4
	}
	if cfg.Registry.CacheDir == "" {
		cfg.Registry.CacheDir = filepath.Join(homeDir, ".devdesk", "cache", "templates")
	}
	// Migrate old single-registry config to the new Registries list
	if cfg.Registry.URL != "" && len(cfg.Registry.Registries) == 0 {
		cfg.Registry.Registries = []RegistryItem{{
			URL:      cfg.Registry.URL,
			Username: cfg.Registry.Username,
			AuthMode: AuthCredentials,
		}}
	}
	if cfg.Scan.CacheDir == "" {
		cfg.Scan.CacheDir = filepath.Join(homeDir, ".devdesk", "cache", "scans")
	}
	if cfg.Scan.MaxCachedReports == 0 {
		cfg.Scan.MaxCachedReports = 50
	}
	if cfg.Scan.Timeout == 0 {
		cfg.Scan.Timeout = 300
	}
	if cfg.Scan.MaxConcurrentScans == 0 {
		cfg.Scan.MaxConcurrentScans = 3
	}
	// An address the file does not carry is the default, never "nowhere":
	// a bind that silently does not happen would look exactly like a server
	// that is off, and `mcp.enabled` is what answers that question.
	if cfg.MCP.Listen == "" {
		cfg.MCP.Listen = DefaultMCPListen
	}

	// Auto is the historical resolution, so a config that predates the setting
	// keeps behaving exactly as it did.
	if cfg.Scan.TrivySource == "" {
		cfg.Scan.TrivySource = ToolSourceAuto
	}
	if cfg.Scan.GitleaksSource == "" {
		cfg.Scan.GitleaksSource = ToolSourceAuto
	}
	if cfg.Scan.PlumberSource == "" {
		cfg.Scan.PlumberSource = ToolSourceAuto
	}

	if cfg.Network.CheckTimeout == 0 {
		cfg.Network.CheckTimeout = DefaultCheckTimeout
	}
	if cfg.Network.PingCount == 0 {
		cfg.Network.PingCount = DefaultPingCount
	}
	if cfg.Network.CertExpiryWarnDays == 0 {
		cfg.Network.CertExpiryWarnDays = DefaultCertExpiryWarnDays
	}
	if cfg.Network.PortsRefreshInterval == 0 {
		cfg.Network.PortsRefreshInterval = DefaultPortsRefreshInterval
	}

	// Backward compat: configs created before the scan-option booleans were introduced
	// will have all of them at Go's zero value (false). Treat "all disabled" as
	// "never configured" and apply sensible defaults so scans work out of the box.
	//
	// EnableCIScore is read here but never written below, and the asymmetry is
	// the point. It is newer than the four, so a file that predates them has it
	// false too and the migration still fires; but "the four off and CI on" is a
	// deliberate configuration — the user asked for CI alone — and forcing vuln
	// and secret back on would overwrite it on every load. Leaving it out of the
	// condition is what a test caught.
	if !cfg.Scan.EnableVuln && !cfg.Scan.EnableSecret && !cfg.Scan.EnableMisconfig &&
		!cfg.Scan.EnableLicense && !cfg.Scan.EnableCIScore {
		cfg.Scan.EnableVuln = true
		cfg.Scan.EnableSecret = true
	}

	// Last, so that the registry migrated from the legacy single-registry keys
	// above gets a slug like every other one.
	return normalizeRegistries(cfg.Registry.Registries)
}

// Default returns the default configuration
func Default() *Config {
	homeDir, _ := os.UserHomeDir()
	return &Config{
		App: AppConfig{
			Theme:           "default",
			LogFile:         filepath.Join(homeDir, ".devdesk", "devdesk.log"),
			DefaultView:     "dashboard",
			WorkspacesDir:   filepath.Join(homeDir, "workspaces"),
			IDECommand:      "code",
			SecretBackend:   "auto",
			ContainerEngine: EngineAuto,
		},
		Status: StatusConfig{
			RefreshInterval: 10,
			AutoRefresh:     true,
			Timeout:         5,
			Components:      []ComponentConfig{},
		},
		Forge: ForgeConfig{
			Type:              ForgeGitLab,
			DefaultVisibility: "private",
			CloneMethod:       "https",
			Pull: ForgePullConfig{
				ParallelJobs:    4,
				IncludeArchived: false,
			},
		},
		Registry: RegistryConfig{
			CacheDir: filepath.Join(homeDir, ".devdesk", "cache", "templates"),
		},
		Scan: ScanConfig{
			TrivySource:        ToolSourceAuto,
			TrivyPath:          "", // Auto-detect in PATH
			GitleaksSource:     ToolSourceAuto,
			GitleaksPath:       "", // Auto-detect in PATH
			PlumberSource:      ToolSourceAuto,
			PlumberPath:        "", // Auto-detect in PATH
			CacheDir:           filepath.Join(homeDir, ".devdesk", "cache", "scans"),
			MaxCachedReports:   50,
			Timeout:            300, // 5 minutes
			MaxConcurrentScans: 3,
			EnableVuln:         true,
			EnableSecret:       true,
		},
		MCP: MCPConfig{
			Listen: DefaultMCPListen,
		},
		Network: NetworkConfig{
			CheckTimeout:         DefaultCheckTimeout,
			PingCount:            DefaultPingCount,
			CertExpiryWarnDays:   DefaultCertExpiryWarnDays,
			PortsRefreshInterval: DefaultPortsRefreshInterval,
		},
	}
}

// ConfigDir returns the configuration directory
func ConfigDir() (string, error) {
	homeDir, err := os.UserHomeDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(homeDir, ".devdesk"), nil
}

// EnsureConfigDir creates the configuration directory if it does not exist
func EnsureConfigDir() error {
	dir, err := ConfigDir()
	if err != nil {
		return err
	}

	return os.MkdirAll(dir, 0755)
}

// Save saves the configuration to the current context's file
func Save(cfg *Config) error {
	ctx, err := GetCurrentContext()
	if err != nil {
		// Fallback to default on error
		ctx = "default"
	}

	return SaveContext(cfg, ctx)
}

// Context Management Functions

// GetCurrentContext reads the current context name from .current-context
// Returns "default" if the file does not exist or is empty
func GetCurrentContext() (string, error) {
	homeDir, err := os.UserHomeDir()
	if err != nil {
		return "", err
	}

	contextFile := filepath.Join(homeDir, ".devdesk", ".current-context")

	// If the file does not exist, return "default"
	if _, err := os.Stat(contextFile); os.IsNotExist(err) {
		return "default", nil
	}

	data, err := os.ReadFile(contextFile)
	if err != nil {
		return "", err
	}

	context := strings.TrimSpace(string(data))
	if context == "" {
		return "default", nil
	}

	return context, nil
}

// CurrentContextName returns the current context, falling back to "default"
// when it cannot be read.
//
// Everything that needs the context name to scope something — Load, Save, the
// scan caches — wants a name and has no use for the error, since a home
// directory that cannot be resolved leaves nothing better to do than assume the
// default context. Three copies of that fallback existed before this.
func CurrentContextName() string {
	ctx, err := GetCurrentContext()
	if err != nil {
		return "default"
	}
	return ctx
}

// SetCurrentContext writes the context name to .current-context
func SetCurrentContext(name string) error {
	if err := ValidateContextName(name); err != nil {
		return err
	}

	homeDir, err := os.UserHomeDir()
	if err != nil {
		return err
	}

	contextFile := filepath.Join(homeDir, ".devdesk", ".current-context")

	// Ensure the directory exists
	if err := EnsureConfigDir(); err != nil {
		return err
	}

	return os.WriteFile(contextFile, []byte(name), 0600)
}

// ListContexts discovers the available contexts by listing config-*.yaml files
// Returns a slice of context names (without the "config-" prefix or ".yaml" suffix)
// Always includes "default" if config.yaml exists
func ListContexts() ([]string, error) {
	homeDir, err := os.UserHomeDir()
	if err != nil {
		return nil, err
	}

	configDir := filepath.Join(homeDir, ".devdesk")
	contexts := []string{}

	// Check the default context
	defaultPath := filepath.Join(configDir, "config.yaml")
	if _, err := os.Stat(defaultPath); err == nil {
		contexts = append(contexts, "default")
	}

	// Glob for named contexts
	pattern := filepath.Join(configDir, "config-*.yaml")
	matches, err := filepath.Glob(pattern)
	if err != nil {
		return nil, err
	}

	for _, match := range matches {
		// Extract the name: config-{name}.yaml -> {name}
		basename := filepath.Base(match)
		name := strings.TrimPrefix(basename, "config-")
		name = strings.TrimSuffix(name, ".yaml")
		contexts = append(contexts, name)
	}

	return contexts, nil
}

// LoadContext loads the configuration for a specific context
// contextName = "default" -> config.yaml
// contextName = "dev" -> config-dev.yaml
func LoadContext(contextName string) (*Config, error) {
	if err := ValidateContextName(contextName); err != nil {
		return nil, err
	}

	configPath, err := GetContextPath(contextName)
	if err != nil {
		return nil, err
	}

	// Check whether the file exists
	if _, err := os.Stat(configPath); os.IsNotExist(err) {
		return nil, fmt.Errorf("context '%s' does not exist (no file at %s)", contextName, configPath)
	}

	// Read and parse YAML
	data, err := os.ReadFile(configPath)
	if err != nil {
		return nil, err
	}

	var cfg Config
	if err := yaml.Unmarshal(data, &cfg); err != nil {
		return nil, fmt.Errorf("failed to parse context '%s': %w", contextName, err)
	}

	// Apply the default values
	if err := applyDefaults(&cfg); err != nil {
		return nil, fmt.Errorf("invalid context '%s': %w", contextName, err)
	}

	// Expand paths (tildes)
	if home, err := os.UserHomeDir(); err == nil {
		cfg.ExpandPaths(home)
	}

	return &cfg, nil
}

// ExpandPaths expands tildes (~) in configuration paths
func (c *Config) ExpandPaths(homeDir string) {
	expand := func(path string) string {
		if strings.HasPrefix(path, "~/") {
			return filepath.Join(homeDir, path[2:])
		}
		return path
	}

	c.App.LogFile = expand(c.App.LogFile)
	c.App.WorkspacesDir = expand(c.App.WorkspacesDir)
	c.Registry.CacheDir = expand(c.Registry.CacheDir)
	c.Scan.CacheDir = expand(c.Scan.CacheDir)
	c.Scan.TrivyPath = expand(c.Scan.TrivyPath)
	c.Scan.GitleaksPath = expand(c.Scan.GitleaksPath)
	c.Scan.GitleaksConfig = absolute(expand(c.Scan.GitleaksConfig))
	c.Scan.PlumberConfig = absolute(expand(c.Scan.PlumberConfig))
}

// absolute pins a configured file path to one meaning.
//
// A relative gitleaks_config does not mean the same thing on both sides of the
// Docker boundary — DevDesk's working directory in binary mode, the container's
// in Docker mode — and the file is now mounted, so the two readings would
// disagree about which file is scanned with. Resolving it here settles it
// against DevDesk's own working directory, once, at load: the path that gets
// mounted and the path the configuration view shows are then the same string.
//
// A path that cannot be resolved is left as it was rather than dropped:
// RunGitleaks refuses an unreadable config with the reason, and that is a
// better place to fail than a config file that silently loses a setting.
func absolute(path string) string {
	if path == "" {
		return ""
	}
	abs, err := filepath.Abs(path)
	if err != nil {
		return path
	}
	return abs
}

// SaveContext saves the configuration to a specific context file
func SaveContext(cfg *Config, contextName string) error {
	if err := ValidateContextName(contextName); err != nil {
		return err
	}

	configPath, err := GetContextPath(contextName)
	if err != nil {
		return err
	}

	// Ensure the directory exists
	if err := EnsureConfigDir(); err != nil {
		return err
	}

	// Marshal to YAML
	data, err := yaml.Marshal(cfg)
	if err != nil {
		return err
	}

	// Write the file
	return os.WriteFile(configPath, data, 0600)
}

// ContextExists checks whether a context configuration file exists
func ContextExists(contextName string) (bool, error) {
	if err := ValidateContextName(contextName); err != nil {
		return false, err
	}

	configPath, err := GetContextPath(contextName)
	if err != nil {
		return false, err
	}

	_, err = os.Stat(configPath)
	if os.IsNotExist(err) {
		return false, nil
	}
	if err != nil {
		return false, err
	}

	return true, nil
}

// GetContextPath returns the file path for a context
// "default" -> ~/.devdesk/config.yaml
// "dev" -> ~/.devdesk/config-dev.yaml
func GetContextPath(contextName string) (string, error) {
	homeDir, err := os.UserHomeDir()
	if err != nil {
		return "", err
	}

	configDir := filepath.Join(homeDir, ".devdesk")

	var filename string
	if contextName == "default" {
		filename = "config.yaml"
	} else {
		filename = fmt.Sprintf("config-%s.yaml", contextName)
	}

	return filepath.Join(configDir, filename), nil
}

// ValidateContextName validates the format of the context name
// Must be "default" or match ^[a-z0-9-]+$
func ValidateContextName(name string) error {
	if name == "default" {
		return nil
	}

	// Pattern: lowercase letters, digits, hyphens
	matched, err := regexp.MatchString("^[a-z0-9-]+$", name)
	if err != nil {
		return err
	}

	if !matched {
		return fmt.Errorf("invalid context name '%s': must contain only lowercase letters, numbers, and hyphens", name)
	}

	return nil
}

// CreateContext creates a new context with a default configuration
// Empty monitors, empty GitLab URL, other values default
func CreateContext(contextName string) error {
	if err := ValidateContextName(contextName); err != nil {
		return err
	}

	// Check whether it already exists
	exists, err := ContextExists(contextName)
	if err != nil {
		return err
	}
	if exists {
		return fmt.Errorf("context '%s' already exists", contextName)
	}

	// Create config with defaults
	cfg := Default()

	// Clear monitors and forge for the new context
	cfg.Status.Components = []ComponentConfig{}
	cfg.Forge.URL = ""

	// Save
	return SaveContext(cfg, contextName)
}

package config

// The container engine names. They are stated here as well as in
// internal/engine, and TestEveryConfiguredEngineHasAShape keeps the two in
// step — the same arrangement the forge names have (§3.6) and the registry
// `provider` names have (§3.8). config must not import a backend, and a
// backend must not be the authority on what a config file may say, so a test
// is the only thing that can hold them together.
const (
	// EngineAuto is the default: docker if it is on PATH, else podman. It
	// spares anyone who installed exactly one of the two a setting they have
	// no opinion about — app.secret_backend's precedent (§3.9).
	EngineAuto   = "auto"
	EngineDocker = "docker"
	EnginePodman = "podman"
)

// ContainerEngines lists the values app.container_engine names, in the order
// the configuration view cycles them.
//
// It is not the whole set the setting accepts: an explicit path to a binary is
// also honoured (internal/engine.Resolve), and is deliberately not cycled —
// there is nothing to cycle through. The same compromise scan.trivy_path makes.
func ContainerEngines() []string { return []string{EngineAuto, EngineDocker, EnginePodman} }

package config

// The forge vocabulary. It is stated here as well as in internal/forge, and
// TestTheForgeVocabularyMatchesTheBackends keeps the two in step — the same
// arrangement the registry `provider` names have between config and
// registrymgr (§3.8). A config value that no backend answers to would resolve
// to nothing at load, which is a failure mode worth a test rather than a
// comment.
const (
	// ForgeGitLab is the default, and what every file written before `type:`
	// existed means.
	ForgeGitLab = "gitlab"
	ForgeGitHub = "github"
)

// ForgeTypes lists what `forge.type` accepts, in the order the configuration
// view cycles them.
func ForgeTypes() []string { return []string{ForgeGitLab, ForgeGitHub} }

// migrateGitLabSection carries a legacy `gitlab:` block into `forge:`.
//
// Field by field, and only where the new value is empty: a file that already
// carries `forge:` keeps it, so a half-written file does not have its new
// values overwritten by its old ones. The legacy struct is cleared once read,
// so the key leaves the file on the next save — the precedent is
// RegistryItem.AuthEnabled and, right below this in applyDefaults,
// `docker.network_tool_image`.
//
// It runs **before** the defaults. yaml.Unmarshal is not strict here, so an
// un-migrated block is dropped in silence, and the silence would point a
// context at no host at all.
func migrateGitLabSection(cfg *Config) {
	legacy := cfg.GitLab
	if legacy == (GitLabConfig{}) {
		return
	}
	defer func() {
		// A legacy file predates `type:` by definition, so it can only mean
		// GitLab. Cleared last, so the key leaves the file on the next save.
		if cfg.Forge.Type == "" {
			cfg.Forge.Type = ForgeGitLab
		}
		cfg.GitLab = GitLabConfig{}
	}()

	// Nothing under `forge:` at all — the ordinary case, and the only one where
	// a bool can be carried over safely: IncludeArchived's zero value *is*
	// false, so no per-field guard could tell "unset" from "deliberately off".
	if cfg.Forge == (ForgeConfig{}) {
		cfg.Forge = ForgeConfig{
			URL:                legacy.URL,
			DefaultParentGroup: legacy.DefaultParentGroup,
			DefaultVisibility:  legacy.DefaultVisibility,
			CloneMethod:        legacy.CloneMethod,
			Pull: ForgePullConfig{
				ParallelJobs:    legacy.Pull.ParallelJobs,
				IncludeArchived: legacy.Pull.IncludeArchived,
			},
		}
		return
	}

	// Both blocks are present, which a hand-edited file can be. The new one
	// wins field by field: its values were written later, and overwriting them
	// with the old ones would undo the edit that created the situation.
	if cfg.Forge.URL == "" {
		cfg.Forge.URL = legacy.URL
	}
	if cfg.Forge.DefaultParentGroup == "" {
		cfg.Forge.DefaultParentGroup = legacy.DefaultParentGroup
	}
	if cfg.Forge.DefaultVisibility == "" {
		cfg.Forge.DefaultVisibility = legacy.DefaultVisibility
	}
	if cfg.Forge.CloneMethod == "" {
		cfg.Forge.CloneMethod = legacy.CloneMethod
	}
	if cfg.Forge.Pull.ParallelJobs == 0 {
		cfg.Forge.Pull.ParallelJobs = legacy.Pull.ParallelJobs
	}
}

package forge

import "github.com/anthnel/devdesk/internal/config"

// Vocabulary is what a forge is *called*, as opposed to what it can do.
//
// The distinction is §3.6's: "Group" against "Organization" is a **word**,
// while nesting depth and the visibility set are **shapes** — they change what
// the application can promise, and no wording helps with them. Shape carries
// the second; this carries the first, and neither grows conditionals for the
// other.
//
// # Per forge, not neutral
//
// A GitLab user says *group*, a GitHub user says *repository*. "Namespace" is a
// third language nobody speaks, and it makes the application read as an
// abstraction layer rather than as a tool. So every word here is the one its
// forge's own documentation uses.
//
// The field names are neutral because the *code* has to be — a view cannot
// switch on which forge it is talking to — but nothing a user reads is.
//
// # No view writes a forge's name into a string
//
// That is the rule this type exists to make checkable, and
// TestNoViewNamesAForge (internal/ui/vocabtest) walks every string literal
// under internal/ui to enforce it. A command name is not covered: it is routing
// identity, the same for both forges, and lives in internal/command.
type Vocabulary struct {
	// Name is the forge as it names itself — "GitLab", "GitHub". Capitalised:
	// it is a proper noun, and it is what titles and messages interpolate.
	Name string

	// Namespace holds repositories and, on some forges, other namespaces.
	Namespace, Namespaces string

	// Repository is one repository.
	Repository, Repositories string

	// ChangeRequest is a proposal to merge a branch.
	ChangeRequest, ChangeRequests string

	// ChangeRequestShort is the initialism — "MR", "PR". The dashboard's tree
	// nodes are eleven cells wide, so the long form does not fit and truncating
	// it would produce "Merge Req…" on one forge and "Pull Requ…" on the other.
	ChangeRequestShort string

	// TokenLabel is what the auth view calls the secret it asks for.
	TokenLabel string

	// TokenPlaceholder is an example token, shown greyed in the input until the
	// user types.
	//
	// It is a hint and never a check: DevDesk does not validate the prefix, and
	// a forge that changes its format must not turn a working token into a
	// refused one. Shaped like a real value rather than as prose, because that
	// is what a placeholder is — the prose about which prefixes exist lives in
	// TokenHelp, where there is room to name more than one.
	TokenPlaceholder string

	// TokenHelp says where to create a token and which scopes it needs. One
	// sentence, because it is rendered in a help pane beside others.
	TokenHelp string

	// ExampleURL is what the configuration view suggests as a host. The public
	// instance, because it is the only address that is the same for everyone —
	// a self-hosted example would be a hostname nobody has.
	ExampleURL string
}

// gitlabVocabulary and githubVocabulary are the two, written out rather than
// derived: every word is a decision about what that forge's users call things,
// and a rule that produced them would be a rule about English rather than about
// either product.
var (
	gitlabVocabulary = Vocabulary{
		Name:               "GitLab",
		Namespace:          "Group",
		Namespaces:         "Groups",
		Repository:         "Project",
		Repositories:       "Projects",
		ChangeRequest:      "Merge Request",
		ChangeRequests:     "Merge Requests",
		ChangeRequestShort: "MR",
		TokenLabel:         "Personal Access Token",
		TokenPlaceholder:   "glpat-…",
		TokenHelp:          "Create a token in GitLab > Settings > Access Tokens. Required scopes: api, read_user.",
		ExampleURL:         "https://gitlab.com",
	}

	githubVocabulary = Vocabulary{
		Name:               "GitHub",
		Namespace:          "Organization",
		Namespaces:         "Organizations",
		Repository:         "Repository",
		Repositories:       "Repositories",
		ChangeRequest:      "Pull Request",
		ChangeRequests:     "Pull Requests",
		ChangeRequestShort: "PR",
		TokenLabel:         "Personal Access Token",
		TokenPlaceholder:   "ghp_… or github_pat_…",
		TokenHelp:          "Create a token in GitHub > Settings > Developer settings > Personal access tokens. Required scopes: repo, read:org.",
		ExampleURL:         "https://github.com",
	}
)

// VocabularyFor resolves the wording for a configured forge type.
//
// It takes the **configured** type rather than a live Forge, and that is
// deliberate: the explorer's "not authenticated" screen and the auth view's own
// title both need the words before any session exists. A method on Forge would
// be unavailable exactly where the words are needed most.
//
// An unknown type falls back to GitLab rather than to an empty Vocabulary. A
// screen with no nouns on it is a worse failure than a screen using the wrong
// forge's nouns, and config.applyDefaults already guarantees a known value —
// this is the belt to that brace.
func VocabularyFor(forgeType string) Vocabulary {
	switch forgeType {
	case config.ForgeGitHub:
		return githubVocabulary
	default:
		return gitlabVocabulary
	}
}

package credentials

import (
	"bytes"
	"context"
	"os/exec"
	"strings"
	"time"
)

// Backend names where a secret actually ends up.
type Backend string

const (
	// BackendKeyring is the host's own secret manager. The only backend that
	// can promise the secret is not sitting in a plaintext file somewhere.
	BackendKeyring Backend = "keyring"

	// BackendGitCredential delegates to git's configured credential helper.
	// Honest only as far as that helper is: `store` writes plaintext, which is
	// why gitHelperUsable refuses it.
	BackendGitCredential Backend = "git-credential"

	// BackendMemory holds the secret for this session and nothing longer. It is
	// the fallback, and it is deliberately the worst one — see Selection.Detail.
	BackendMemory Backend = "memory"
)

// Preference values accepted from app.secret_backend in the configuration.
const (
	PreferenceAuto          = "auto"
	PreferenceKeyring       = "keyring"
	PreferenceGitCredential = "git-credential"
)

// gitConfigTimeout bounds the `git config` read that inspects the helper. Same
// reasoning as credentialTimeout: a blocked git call must not freeze the TUI.
const gitConfigTimeout = 2 * time.Second

// Selection is a storage together with the answer to "where does the secret go".
// The UI needs both: it has to tell the user which store a token was written
// to, and warn them when the answer is "nowhere that survives this session".
type Selection struct {
	Storage Storage
	Backend Backend

	// Detail is a sentence for the user, naming the store or explaining why
	// there is none. Always populated.
	Detail string
}

// Persists reports whether a secret saved here survives the process.
func (s Selection) Persists() bool {
	return s.Backend != BackendMemory
}

// Select resolves the storage for a context.
//
// The order is deliberate and there is exactly one destination — writing to
// several at once is what made the old "secure" option store the token in the
// credential manager *and* in a plaintext file (§3.9):
//
//  1. the host secret store, when one answers;
//  2. git's credential helper, when git is configured with one that does not
//     itself write plaintext;
//  3. memory, for this session only.
//
// preference comes from app.secret_backend and pins the head of that list.
// A pinned backend that turns out to be unreachable falls through to memory
// rather than silently to the other one: someone who asked for the keyring
// should not get a git helper without being told.
//
// The returned Selection must be kept for the lifetime of the context. Calling
// Select again yields a fresh MemoryStorage, and a token saved into the old one
// would be invisible to it.
func Select(contextName, preference string) Selection {
	switch preference {
	case PreferenceKeyring:
		if KeyringAvailable() {
			return keyringSelection(contextName)
		}
		return memorySelection(KeyringName() + " is configured but not reachable")

	case PreferenceGitCredential:
		if helper, ok := gitHelperUsable(); ok {
			return gitSelection(contextName, helper)
		}
		return memorySelection("git is not configured with a credential helper that stores secrets safely")
	}

	if KeyringAvailable() {
		return keyringSelection(contextName)
	}
	if helper, ok := gitHelperUsable(); ok {
		return gitSelection(contextName, helper)
	}
	return memorySelection("no " + KeyringName() + " and no usable git credential helper")
}

func keyringSelection(contextName string) Selection {
	return Selection{
		Storage: NewKeyringStorage(contextName),
		Backend: BackendKeyring,
		Detail:  "Secrets are stored in the " + KeyringName() + ".",
	}
}

func gitSelection(contextName, helper string) Selection {
	return Selection{
		Storage: NewGitCredentialStorageWithContext(contextName),
		Backend: BackendGitCredential,
		Detail:  "Secrets are stored by the git credential helper (" + helper + ").",
	}
}

// SessionOnly returns a Selection that keeps secrets in this process and
// nowhere else. Select falls back to it, and the router starts on it before it
// has resolved a real backend — a Selection is never nil, so nothing has to
// guard against a missing store.
func SessionOnly(why string) Selection {
	return Selection{
		Storage: NewMemoryStorage(),
		Backend: BackendMemory,
		Detail:  "Nothing is saved — " + why + ". You will have to authenticate again next launch.",
	}
}

func memorySelection(why string) Selection {
	return SessionOnly(why)
}

// gitHelperUsable reports whether git has a credential helper configured that
// is worth delegating to, and names it.
//
// `store` is refused by name: it keeps credentials in ~/.git-credentials in
// plaintext, which is the failure this whole change exists to remove — moving
// the token from one plaintext file to another is not a fix. An unset helper is
// refused too, since git would then have nowhere to put the secret and would
// quietly succeed at storing nothing.
//
// Every other helper is accepted. There is no list of the good ones to check
// against: `manager`, `osxkeychain`, `libsecret`, `wincred` and any number of
// third-party helpers all reach a real store, and enumerating them would only
// mean rejecting the next one someone installs.
func gitHelperUsable() (string, bool) {
	ctx, cancel := context.WithTimeout(context.Background(), gitConfigTimeout)
	defer cancel()

	cmd := exec.CommandContext(ctx, "git", "config", "--get-all", "credential.helper")
	var stdout bytes.Buffer
	cmd.Stdout = &stdout
	cmd.WaitDelay = credentialWaitDelay
	if err := cmd.Run(); err != nil {
		return "", false
	}

	// git resolves the last helper that answers, so read them in that order and
	// take the first usable one from the end.
	lines := strings.Split(strings.TrimSpace(stdout.String()), "\n")
	for i := len(lines) - 1; i >= 0; i-- {
		if name, ok := usableHelperName(lines[i]); ok {
			return name, true
		}
	}
	return "", false
}

// usableHelperName extracts the helper name from one credential.helper value
// and reports whether it stores secrets somewhere other than a plaintext file.
func usableHelperName(value string) (string, bool) {
	value = strings.TrimSpace(value)
	if value == "" {
		return "", false
	}

	// A value may carry arguments (`store --file=/path`), and a leading `!`
	// marks a shell command. Only the first word names the helper.
	name := strings.TrimPrefix(strings.Fields(value)[0], "!")
	if name == "store" {
		return "", false
	}
	return name, true
}

package components

import (
	"strings"

	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/ui/theme"
)

// ConfirmModal is a confirmation dialog box
type ConfirmModal struct {
	title   string
	message string
	focused bool // true = Yes, false = No
	width   int
	height  int
}

// NewConfirmModal creates a new confirmation modal
func NewConfirmModal(title, message string) *ConfirmModal {
	return &ConfirmModal{
		title:   title,
		message: message,
		focused: false, // Defaults to "No" to avoid accidental deletions
	}
}

// ConfirmModalYesMsg is sent when the user confirms
type ConfirmModalYesMsg struct{}

// ConfirmModalNoMsg is sent when the user cancels
type ConfirmModalNoMsg struct{}

// Update updates the modal
func (m *ConfirmModal) Update(msg tea.Msg) (*ConfirmModal, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height

	case tea.KeyMsg:
		switch msg.String() {
		case "left", "right":
			// Toggle between Yes and No (Rule 135 — Tab exclusively for tabs)
			m.focused = !m.focused
			return m, nil

		case "enter", " ":
			// Confirm the selection
			if m.focused {
				return m, func() tea.Msg {
					return ConfirmModalYesMsg{}
				}
			} else {
				return m, func() tea.Msg {
					return ConfirmModalNoMsg{}
				}
			}

		case "y", "Y":
			// Shortcut for Yes
			return m, func() tea.Msg {
				return ConfirmModalYesMsg{}
			}

		case "n", "N", "esc":
			// Shortcut for No
			return m, func() tea.Msg {
				return ConfirmModalNoMsg{}
			}
		}
	}

	return m, nil
}

// View renders the modal
func (m *ConfirmModal) View() string {
	var b strings.Builder

	// Title
	b.WriteString(theme.TitleStyle.Render(m.title))
	b.WriteString("\n\n")

	// Message
	b.WriteString(m.message)
	b.WriteString("\n\n")

	// Buttons
	yes := theme.RenderButton("Yes", m.focused, "danger")
	no := theme.RenderButton("No", !m.focused, "primary")

	buttons := yes + theme.Bg("  ") + no
	b.WriteString(buttons)
	b.WriteString("\n\n")

	return lipgloss.NewStyle().
		Background(theme.ColorBackground).
		Foreground(theme.ColorText).
		Border(lipgloss.NormalBorder()).
		BorderForeground(theme.ColorError).
		BorderBackground(theme.ColorBackground).
		Padding(1, 2).
		Render(b.String())
}

package components

import (
	"fmt"
	"github.com/anthnel/devdesk/internal/forge"
	"strings"

	"github.com/charmbracelet/bubbles/textinput"
	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/ui/theme"
)

// descWrapWidth is the number of runes per visual line for the description field.
const descWrapWidth = 80

// FormType represents the type of creation form
type FormType int

const (
	FormTypeGroup FormType = iota
	FormTypeProject
)

// resourceTypeLabels are what the two kinds are called, in cycle order. They
// come from the forge's vocabulary rather than being written here: a GitLab
// user creates a Group or a Project, a GitHub user an Organization or a
// Repository, and this component knows neither (§3.6).
func resourceTypeLabels(v forge.Vocabulary) [2]string {
	return [2]string{v.Namespace, v.Repository}
}

// CreationForm is a form for creating GitLab groups or projects
type CreationForm struct {
	resourceType   int       // 0=namespace, 1=repository
	resourceLabels [2]string // the forge's words for the two, in cycle order
	formType       FormType  // kept in sync with resourceType
	parentName     string    // Name of parent group (for display)
	// parentID is the forge's opaque identifier for the parent namespace, empty
	// at the root. It was an int64 — GitLab's numeric id — which is exactly what
	// §3.6 made opaque: the form carries it and never reads it.
	parentID        string
	nameInput       textinput.Model
	descInput       WrappedInput
	visibility      int      // 0=private, 1=internal, 2=public
	visibilities    []string // visibility options
	templates       []string // for projects: available templates
	templateIdx     int      // selected template index
	templateScroll  int      // scroll offset for template dropdown
	templateWarning string   // warning message if template loading failed
	// focusedField: 0=resourceType, 1=name, 2=desc, 3=visibility, 4=template (project only), 4or5=submit
	focusedField int
	width        int
	height       int
	err          string
}

// CreationFormSubmitMsg is sent when form is submitted
type CreationFormSubmitMsg struct {
	FormType    FormType
	Name        string
	Description string
	Visibility  string
	Template    string // for projects
	ParentID    string
}

// CreationFormCancelMsg is sent when form is cancelled
type CreationFormCancelMsg struct{}

// Description character limit (GitLab limit is 250)
const descriptionCharLimit = 250

// maxVisibleTemplates is the maximum number of templates visible in the dropdown
const maxVisibleTemplates = 7

// formTypeFromResourceType converts a resource type index to FormType.
func formTypeFromResourceType(rt int) FormType {
	if rt == 1 {
		return FormTypeProject
	}
	return FormTypeGroup
}

// NewCreationForm creates the unified group/project creation form.
// defaultResourceType: 0=Group, 1=Project.
// focusedField starts at 0 (Type) so the user can immediately cycle the resource type.
func NewCreationForm(defaultResourceType int, parentName string, parentID string, defaultVisibility string, templates []string, v forge.Vocabulary) *CreationForm {
	nameInput := textinput.New()
	nameInput.Placeholder = "name"
	nameInput.CharLimit = 100
	nameInput.Width = 50
	theme.StyleTextInput(&nameInput)

	descInput := NewWrappedInput(descWrapWidth, descriptionCharLimit, "description (optional)")

	visibilities := []string{"private", "internal", "public"}
	visIdx := 0
	for i, v := range visibilities {
		if v == defaultVisibility {
			visIdx = i
			break
		}
	}

	// Add "none" template option at the beginning
	allTemplates := append([]string{"none"}, templates...)

	return &CreationForm{
		resourceType:   defaultResourceType,
		resourceLabels: resourceTypeLabels(v),
		formType:       formTypeFromResourceType(defaultResourceType),
		parentName:     parentName,
		parentID:       parentID,
		nameInput:      nameInput,
		descInput:      descInput,
		visibility:     visIdx,
		visibilities:   visibilities,
		templates:      allTemplates,
		templateIdx:    0,
		focusedField:   0, // start on Type
	}
}

// SetTemplateWarning sets a warning message displayed near the template field
func (f *CreationForm) SetTemplateWarning(msg string) {
	f.templateWarning = msg
}

// Update handles messages
func (f *CreationForm) Update(msg tea.Msg) (*CreationForm, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		f.width = msg.Width
		f.height = msg.Height
		f.descInput.SetDisplayWidth(msg.Width)

	case tea.KeyMsg:
		return f.handleKeyMsg(msg)
	}

	// Update focused text input
	var cmd tea.Cmd
	switch f.focusedField {
	case 1:
		f.nameInput, cmd = f.nameInput.Update(msg)
	case 2:
		f.descInput, cmd = f.descInput.Update(msg)
	}

	return f, cmd
}

// maxField returns the index of the submit button (last field).
func (f *CreationForm) maxField() int {
	if f.resourceType == 1 && len(f.templates) > 0 {
		return 5
	}
	return 4
}

func (f *CreationForm) handleKeyMsg(msg tea.KeyMsg) (*CreationForm, tea.Cmd) {
	max := f.maxField()

	switch msg.String() {
	case "esc":
		return f, func() tea.Msg { return CreationFormCancelMsg{} }

	case "down":
		if f.isOnTemplateField() && f.templateIdx < len(f.templates)-1 {
			f.templateDown()
			return f, nil
		}
		f.focusedField = (f.focusedField + 1) % (max + 1)
		f.updateFocus()
		return f, nil

	case "up":
		if f.isOnTemplateField() && f.templateIdx > 0 {
			f.templateUp()
			return f, nil
		}
		f.focusedField = (f.focusedField - 1 + max + 1) % (max + 1)
		f.updateFocus()
		return f, nil

	case "enter":
		if f.focusedField == max { // Submit button
			return f.submit()
		}
		// On other fields, move to next
		f.focusedField = (f.focusedField + 1) % (max + 1)
		f.updateFocus()
		return f, nil

	case "left", "right":
		// Field 0: cycle resource type (Group ↔ Project)
		if f.focusedField == 0 {
			if msg.String() == "left" {
				f.resourceType = (f.resourceType - 1 + len(f.resourceLabels)) % len(f.resourceLabels)
			} else {
				f.resourceType = (f.resourceType + 1) % len(f.resourceLabels)
			}
			f.formType = formTypeFromResourceType(f.resourceType)
			// No focus clamp here: this branch is only reached with
			// focusedField == 0, and maxField() never drops below 4.
			return f, nil
		}
		// Field 3: cycle visibility
		if f.focusedField == 3 {
			if msg.String() == "left" {
				f.visibility = (f.visibility - 1 + len(f.visibilities)) % len(f.visibilities)
			} else {
				f.visibility = (f.visibility + 1) % len(f.visibilities)
			}
		}
		return f, nil
	}

	// Update text inputs
	var cmd tea.Cmd
	switch f.focusedField {
	case 1:
		f.nameInput, cmd = f.nameInput.Update(msg)
	case 2:
		f.descInput, cmd = f.descInput.Update(msg)
	}

	return f, cmd
}

// isOnTemplateField returns true if the template dropdown has focus
func (f *CreationForm) isOnTemplateField() bool {
	return f.focusedField == 4 && f.resourceType == 1 && len(f.templates) > 0
}

// templateDown moves template selection down by one
func (f *CreationForm) templateDown() {
	if f.templateIdx < len(f.templates)-1 {
		f.templateIdx++
		f.adjustTemplateScroll()
	}
}

// templateUp moves template selection up by one
func (f *CreationForm) templateUp() {
	if f.templateIdx > 0 {
		f.templateIdx--
		f.adjustTemplateScroll()
	}
}

// adjustTemplateScroll ensures the selected template is visible in the dropdown
func (f *CreationForm) adjustTemplateScroll() {
	// Scroll down if selected is below visible area
	if f.templateIdx >= f.templateScroll+maxVisibleTemplates {
		f.templateScroll = f.templateIdx - maxVisibleTemplates + 1
	}
	// Scroll up if selected is above visible area
	if f.templateIdx < f.templateScroll {
		f.templateScroll = f.templateIdx
	}
}

func (f *CreationForm) updateFocus() {
	f.nameInput.Blur()
	f.descInput.Blur()

	switch f.focusedField {
	case 1:
		f.nameInput.Focus()
	case 2:
		f.descInput.Focus()
	}
}

// GetTitle returns the form title for use in the viewport breadcrumb.
// Includes the parent name when applicable: "New Project (parent: group/sub)".
func (f *CreationForm) GetTitle() string {
	base := "New " + f.resourceLabels[f.resourceType]
	if f.parentName != "" {
		parent := lipgloss.NewStyle().Foreground(theme.ColorSecondary).Background(theme.ColorBackground).Render("(parent: " + f.parentName + ")")
		return base + " " + parent
	}
	return base
}

// InEditMode returns true when the form is being edited (for preventing command mode)
func (f *CreationForm) InEditMode() bool {
	return true
}

func (f *CreationForm) submit() (*CreationForm, tea.Cmd) {
	name := strings.TrimSpace(f.nameInput.Value())
	if name == "" {
		f.err = "Name is required"
		return f, nil
	}

	template := ""
	if f.formType == FormTypeProject && len(f.templates) > 0 && f.templateIdx > 0 {
		template = f.templates[f.templateIdx]
	}

	return f, func() tea.Msg {
		return CreationFormSubmitMsg{
			FormType:    f.formType,
			Name:        name,
			Description: strings.TrimSpace(f.descInput.Value()),
			Visibility:  f.visibilities[f.visibility],
			Template:    template,
			ParentID:    f.parentID,
		}
	}
}

// View renders the form
func (f *CreationForm) View() string {
	var b strings.Builder

	b.WriteString(theme.EmptyLineBg(f.width) + "\n")

	// Error message
	if f.err != "" {
		b.WriteString(lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorError).Render("Error: "+f.err) + "\n\n")
	}

	// Resource type selector (cycle ←→)
	b.WriteString(f.renderResourceTypeField())
	b.WriteString("\n\n")

	// Name field
	b.WriteString(f.renderField("Name", f.nameInput.View(), 1))
	b.WriteString("\n\n")

	// Description field (multiline)
	b.WriteString(f.renderDescriptionField())
	b.WriteString("\n\n")

	// Visibility selector
	b.WriteString(f.renderVisibilityField())
	b.WriteString("\n\n")

	// Template dropdown (for projects only)
	if f.resourceType == 1 && len(f.templates) > 0 {
		b.WriteString(f.renderTemplateList())
		b.WriteString("\n\n")
	}

	// Submit button
	b.WriteString("\n")
	b.WriteString("  " + theme.RenderButton("Create", f.focusedField == f.maxField(), "primary"))
	b.WriteString("\n\n")

	// Help is shown in header shortcuts

	// Return without modal border (Rule 112: forms in viewport)
	return b.String()
}

func (f *CreationForm) renderField(label, value string, fieldIdx int) string {
	var labelStr string
	if f.focusedField == fieldIdx {
		labelStr = theme.KeyStyle.Render(theme.IconCircleSmall + " " + label + " " + theme.IconChevronRight)
	} else {
		labelStr = theme.Bg("  " + label + " " + theme.IconChevronRight)
	}
	return labelStr + "\n" + theme.Bg("  ") + value
}

// renderResourceTypeField renders the resource type cycle selector (Rule 132).
func (f *CreationForm) renderResourceTypeField() string {
	label := "Type " + theme.IconSelect + " "
	value := lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorText).
		Render(f.resourceLabels[f.resourceType])
	if f.focusedField == 0 {
		return theme.KeyStyle.Render(theme.IconCircleSmall+" "+label+theme.IconChevronRight+" ") + value
	}
	return theme.Bg("  "+label+theme.IconChevronRight+" ") + value
}

func (f *CreationForm) renderDescriptionField() string {
	charCount := len([]rune(f.descInput.Value()))
	countStyle := theme.DimStyle
	if charCount > descriptionCharLimit-20 {
		countStyle = lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorHighlight)
	}
	if charCount >= descriptionCharLimit {
		countStyle = lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorError)
	}
	countStr := countStyle.Render(fmt.Sprintf(" (%d/%d)", charCount, descriptionCharLimit))

	var labelStr string
	if f.focusedField == 2 {
		labelStr = theme.KeyStyle.Render(theme.IconCircleSmall + " Description " + theme.IconChevronRight)
	} else {
		labelStr = theme.Bg("  Description " + theme.IconChevronRight)
	}

	return labelStr + countStr + "\n" + f.descInput.View()
}

// renderVisibilityField renders the visibility selector in the same single-line format as
// the "Target Type" field in the security view (Rule 115).
func (f *CreationForm) renderVisibilityField() string {
	label := "Visibility " + theme.IconSelect + " "
	value := lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorText).Render(f.visibilities[f.visibility])
	if f.focusedField == 3 {
		return theme.KeyStyle.Render(theme.IconCircleSmall+" "+label+theme.IconChevronRight+" ") + value
	}
	return theme.Bg("  "+label+theme.IconChevronRight+" ") + value
}

// renderTemplateList renders a vertical scrollable dropdown list for template selection
func (f *CreationForm) renderTemplateList() string {
	focused := f.focusedField == 4

	var labelStr string
	if focused {
		labelStr = theme.KeyStyle.Render(theme.IconCircleSmall + " Template " + theme.IconSelect + " " + theme.IconChevronRight + " ")
	} else {
		labelStr = theme.Bg("  Template " + theme.IconSelect + " " + theme.IconChevronRight + " ")
	}

	// Show selected template name next to label when not focused. The warning
	// still goes out: it explains why the list is empty, and a user who never
	// lands on this field would otherwise never learn the registry failed.
	if !focused {
		selected := f.templates[f.templateIdx]
		return labelStr + theme.PrimaryColorStyle.Render(selected) + f.renderTemplateWarning()
	}

	// Focused: render vertical dropdown list
	var b strings.Builder
	b.WriteString(labelStr)
	b.WriteString("\n")

	visibleCount := maxVisibleTemplates
	if len(f.templates) < visibleCount {
		visibleCount = len(f.templates)
	}

	// Scroll indicator: items above
	if f.templateScroll > 0 {
		b.WriteString(theme.DimStyle.Render(fmt.Sprintf("    ↑ %d more", f.templateScroll)))
		b.WriteString("\n")
	}

	// Render visible items
	end := f.templateScroll + visibleCount
	if end > len(f.templates) {
		end = len(f.templates)
	}

	for i := f.templateScroll; i < end; i++ {
		tmpl := f.templates[i]
		if i == f.templateIdx {
			b.WriteString(theme.PrimaryColorStyle.Bold(true).Render("  " + theme.IconCircleSmall + " " + tmpl))
		} else {
			b.WriteString(theme.DimStyle.Render("    " + tmpl))
		}
		if i < end-1 {
			b.WriteString("\n")
		}
	}

	// Scroll indicator: items below
	remaining := len(f.templates) - end
	if remaining > 0 {
		b.WriteString("\n")
		b.WriteString(theme.DimStyle.Render(fmt.Sprintf("    ↓ %d more", remaining)))
	}

	b.WriteString(f.renderTemplateWarning())

	return b.String()
}

// renderTemplateWarning renders the registry failure on its own line, or an
// empty string when the templates loaded. It is appended in both the focused
// and unfocused branches of renderTemplateList: the warning explains why the
// list is empty, so hiding it until the field takes focus tells the user
// nothing at the moment they need it.
func (f *CreationForm) renderTemplateWarning() string {
	if f.templateWarning == "" {
		return ""
	}
	return "\n" + lipgloss.NewStyle().
		Background(theme.ColorBackground).
		Foreground(theme.ColorError).
		Render("    "+theme.IconWarning+" "+f.templateWarning)
}

package components

import (
	"sync/atomic"
	"time"

	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/ui/theme"
)

// FooterMessage is the one line of state every view shows below its viewport
// (Rules 124, 128). It owns both the text and the three-second timer, which is
// what makes it a component rather than a rendering helper: eight views each
// carried their own pair of fields, their own clear message and their own
// lipgloss block, and that is how the errors ended up left-aligned everywhere
// while the notices were centred — nobody ever centred the error branch.
//
// Usage, from Update() only (Rule 110):
//
//	case SomethingFailedMsg:
//	    return m, m.footer.Error("Failed to load — check logs")
//
//	default:
//	    if m.footer.Handle(msg) {
//	        return m, nil
//	    }
//
// And from View(), which stays read-only:
//
//	m.footer.View(width, components.Status{Text: m.actionLine()})

// FooterMsgDuration is how long a timed message stays on screen (Rule 128).
//
// It is an exported var rather than a const because tea.Tick really sleeps, and
// a test that inspects a Cmd carrying this timer — testutil.Msgs runs the whole
// batch — pays the full three seconds per assertion. internal/ui/testutil
// shortens it from its init, so every view test package gets that for free; the
// production value is what this file states and what
// TestAMessageGetsThreeSeconds pins.
var FooterMsgDuration = 3 * time.Second

// Level is a footer message's severity. It decides the colour and nothing else.
//
// The three are defined by what happened, not by how it feels:
//
//	LevelError   — an operation failed, or the system refused it.
//	LevelWarning — the action cannot be honoured as asked, but nothing failed:
//	               a precondition is unmet, or it is already running.
//	LevelInfo    — a neutral fact, or an operation that succeeded.
type Level int

const (
	LevelInfo Level = iota
	LevelWarning
	LevelError
)

// Style returns the style a level renders in.
func (l Level) Style() lipgloss.Style {
	switch l {
	case LevelError:
		return theme.FooterErrorStyle
	case LevelWarning:
		return theme.FooterWarnStyle
	default:
		return theme.FooterInfoStyle
	}
}

// Status is what a view derives on every frame: a progress line, a hint, or a
// table loading its rows. It carries no timer — a batch outlives the three
// seconds a message gets, which is why the sync and prune lines were rendered
// from state rather than assigned to footerInfo in the first place.
//
// It is a parameter of View rather than a field of FooterMessage because it is
// derived, not stored: containers' action line comes from BusyLabels(), which
// changes with no event to push it on.
type Status struct {
	Text string
	// Spinner prepends the current spinner frame — a table loading its rows.
	Spinner bool
	// Level colours the line, and the zero value is LevelInfo, so a status that
	// says nothing about it renders exactly as it always did.
	//
	// A derived state can be a failure as legitimately as it can be progress:
	// "Docker unreachable" is not an event that happened once, it is what is
	// true right now, and a message would expire after three seconds — which is
	// D47 in one field. It needs the colour of an error and the lifetime of a
	// state, and only Status can give it both.
	Level Level
}

// footerMsgSeq numbers messages so a timer can name the one it was started for.
var footerMsgSeq atomic.Uint64

// ClearFooterMsg expires the message identified by ID.
//
// The ID is what makes the type safe to share across packages. Two things would
// otherwise go wrong: a timer started by one view could clear the message of
// whichever view is active when it lands, and — the bug that was already
// present in all eight local implementations — a message set at t+2.9s was
// wiped at t+3s by its predecessor's timer.
type ClearFooterMsg struct{ ID uint64 }

// PostFooterMsg puts a message in whichever footer is on screen.
//
// It exists for the router, which has none of its own: RenderFooter is the
// active view's (internal/app/view.go), and the one thing the router has to say
// — that the MCP server did not start (§3.61) — belongs on screen at startup,
// not in a log. Every view already offers unhandled messages to Handle, so a
// broadcast lands wherever the user is without any view knowing what it is
// about.
//
// It carries its own ID because the timer is the sender's: PostFooter builds
// both, so the rule that a message set without its timer never clears holds
// here too (Rule 128).
//
// **It lands only where a view holds a FooterMessage.** internal/ui/forge/auth
// renders a footer but declares none, so a broadcast posted while that view is
// on screen reaches nobody — and the router switches to it whenever a context
// has no forge credentials. That is a real gap and not a silent one: the only
// broadcast today is the MCP server's, and its state is also on the `mcp` tab
// of the configuration view, which holds it for as long as it is true rather
// than for three seconds. A second use of this door would need auth to declare
// a footer first.
type PostFooterMsg struct {
	ID    uint64
	Level Level
	Text  string
}

// PostFooter builds the broadcast and the timer that expires it.
//
// For the router. A view has its own footer and calls Info, Warn or Error on
// it — going through here would be a second way to do what a field already
// does, and the message would be adopted by whatever view is active rather than
// by the one that meant it.
func PostFooter(level Level, text string) tea.Cmd {
	if text == "" {
		return nil
	}
	id := footerMsgSeq.Add(1)
	return tea.Batch(
		func() tea.Msg { return PostFooterMsg{ID: id, Level: level, Text: text} },
		tea.Tick(FooterMsgDuration, func(time.Time) tea.Msg { return ClearFooterMsg{ID: id} }),
	)
}

// FooterMessage holds the current message, its level and its identity.
type FooterMessage struct {
	text         string
	level        Level
	id           uint64
	spinnerFrame string
}

// Info, Warn and Error set the message and return its expiry timer. Call them
// from Update() and return the Cmd — a message set without its timer never
// clears (Rule 128).
func (f *FooterMessage) Info(text string) tea.Cmd  { return f.set(text, LevelInfo) }
func (f *FooterMessage) Warn(text string) tea.Cmd  { return f.set(text, LevelWarning) }
func (f *FooterMessage) Error(text string) tea.Cmd { return f.set(text, LevelError) }

func (f *FooterMessage) set(text string, level Level) tea.Cmd {
	if text == "" {
		f.Clear()
		return nil
	}
	f.text = text
	f.level = level
	f.id = footerMsgSeq.Add(1)

	id := f.id
	return tea.Tick(FooterMsgDuration, func(time.Time) tea.Msg {
		return ClearFooterMsg{ID: id}
	})
}

// Clear removes the message now, without waiting for its timer.
func (f *FooterMessage) Clear() {
	f.text = ""
	f.level = LevelInfo
	f.id = 0
}

// Handle consumes what the component owns and reports whether it did: a
// ClearFooterMsg addressed to the current message, and a PostFooterMsg from the
// router. A stale expiry is dropped, and so is one belonging to another view:
// both leave the message on screen for the time it was given.
func (f *FooterMessage) Handle(msg tea.Msg) bool {
	switch msg := msg.(type) {
	case PostFooterMsg:
		// Adopted whole, ID included: the timer that will expire it was built
		// with that ID by the sender, and re-numbering it here would leave a
		// message nothing ever clears.
		f.text = msg.Text
		f.level = msg.Level
		f.id = msg.ID
		return true

	case ClearFooterMsg:
		if f.id == 0 || msg.ID != f.id {
			return false
		}
		f.Clear()
		return true
	}
	return false
}

// SetSpinnerFrame stores the frame a loading Status renders with. Call it from
// the view's spinner.TickMsg handler, passing spinner.View().
//
// It takes the **rendered** spinner rather than a bare frame, which is what
// theme.SpinnerMessage took before it: every view already sets its spinner's
// Style to theme.SpinnerStyle(), so the colour is decided there and restyling
// here would nest one sequence inside another.
//
// That is the opposite of the rule for a table cell (Rule 122), and the
// difference is what is doing the measuring. A cell is measured by runewidth,
// which counts an escape's bytes as columns; this line is measured by
// lipgloss.Width, which does not.
func (f *FooterMessage) SetSpinnerFrame(frame string) { f.spinnerFrame = frame }

// IsSet reports whether a message is currently displayed.
func (f *FooterMessage) IsSet() bool { return f.text != "" }

// Text and Level report what is displayed. They exist for tests and for the
// netdiag header, which picks the active tab's message.
func (f *FooterMessage) Text() string { return f.text }
func (f *FooterMessage) Level() Level { return f.level }

// ID identifies the message currently displayed, 0 when there is none. It is
// what the timer names, and it lets a test in another package build the expiry
// this message will receive — running the real Cmd sleeps for three seconds,
// which is a long time to pay per assertion.
func (f *FooterMessage) ID() uint64 { return f.id }

// View renders the footer's line of text, always at the full width and always
// centred — including when it is empty, because Rule 124 budgets a line for it
// whatever it holds.
//
// Precedence: error, warning, info, then the derived status. A failure the user
// has not read yet matters more than the progress of what is still running.
func (f *FooterMessage) View(width int, status Status) string {
	if width <= 0 {
		return ""
	}

	// A timed message wins over the derived status: a failure the user has not
	// read yet matters more than the progress of what is still running.
	//
	// Truncation is not cosmetic — a line wider than the viewport wraps onto a
	// second one, and the router budgeted exactly one (Rule 124). Everything
	// below it would shift by a line.
	if f.text != "" {
		return centerLine(f.level.Style().Render(theme.TruncateWidth(f.text, width)), width)
	}
	if status.Text == "" {
		return theme.EmptyLineBg(width)
	}

	// lipgloss.Width, not theme.StringWidth: the frame arrives already styled,
	// and runewidth would count its escape sequence as columns.
	spinner, budget := "", width
	if status.Spinner && f.spinnerFrame != "" {
		spinner = f.spinnerFrame + theme.Bg(" ")
		budget -= lipgloss.Width(f.spinnerFrame) + 1
	}
	if budget <= 0 {
		return theme.EmptyLineBg(width)
	}
	return centerLine(spinner+status.Level.Style().Render(theme.TruncateWidth(status.Text, budget)), width)
}

// centerLine centres already-styled content on a line filled with the app
// background. lipgloss does not inherit a background (Rule 115), so the padding
// either side has to carry one of its own.
func centerLine(content string, width int) string {
	return lipgloss.NewStyle().
		Background(theme.ColorBackground).
		Width(width).
		Align(lipgloss.Center).
		Render(content)
}

